namespace Aarkam.DDD.Domain;

/// <summary>
/// A cross-cutting infrastructure audit event raised when a brand-new Aggregate Root is successfully materialized and stored.
/// </summary>
/// <remarks>
/// <b>INFRASTRUCTURE DESIGN NOTE:</b> While individual aggregates focus purely on business-meaningful events (e.g., <c>OrderPlaced</c>), 
/// this generic event is generated by the persistence layer (e.g., EF Core SaveChanges Interceptors) to support global, 
/// uniform auditing, analytical logging, and data lake ingestion streams.
/// </remarks>
public sealed class AggregateCreatedEvent : DomainEventBase
{
    /// <summary>
    /// Gets the unique identifier of the user, system principal, or actor who initiated the creation command.
    /// </summary>
    public string CreatorId { get; private set; } = null!;

    /// <summary>
    /// Gets the tenant context identifier partition containing this record.
    /// </summary>
    public string? TenantId { get; private set; }

    /// <summary>
    /// Gets the exact timezone-aware point in time when persistence operations completed.
    /// </summary>
    public DateTimeOffset CreatedAt { get; private set; }

    /// <summary>
    /// Parameterless constructor required for JSON serialization and event-stream rehydration.
    /// </summary>
    private AggregateCreatedEvent() : base() { }

    /// <summary>
    /// Initializes a new instance of the <see cref="AggregateCreatedEvent"/> audit record.
    /// </summary>
    /// <param name="aggregateType">The class type classification name of the target aggregate root.</param>
    /// <param name="aggregateId">The string representation of the target aggregate identity key.</param>
    /// <param name="creatorId">The identity descriptor of the originating actor.</param>
    /// <param name="tenantId">The multi-tenant logical isolation tracking token, if applicable.</param>
    /// <param name="createdAt">The localized timestamp completing the creation event marker.</param>
    public AggregateCreatedEvent(
        string aggregateType,
        string aggregateId,
        string creatorId,
        string? tenantId,
        DateTimeOffset createdAt)
        : base(aggregateType, aggregateId)
    {
        CreatorId = string.IsNullOrWhiteSpace(creatorId) ? throw new ArgumentException("Creator identity mapping cannot be blank.", nameof(creatorId)) : creatorId;
        TenantId = tenantId;
        CreatedAt = createdAt;
    }
}

/// <summary>
/// A cross-cutting infrastructure audit event raised when any existing Aggregate Root undergoes state mutation.
/// </summary>
/// <remarks>
/// Acts as a unified notification block for down-stream caching invalidation systems, audit logs, or CQRS Read-Model projection synthesizers.
/// </remarks>
public sealed class AggregateModifiedEvent : DomainEventBase
{
    /// <summary>
    /// Gets the unique identifier of the security principal who performed the most recent state transformation.
    /// </summary>
    public string ModifierId { get; private set; } = null!;

    /// <summary>
    /// Gets the tenant context identifier partition containing this record.
    /// </summary>
    public string? TenantId { get; private set; }

    /// <summary>
    /// Gets the exact timezone-aware point in time when the mutation was permanently committed.
    /// </summary>
    public DateTimeOffset ModifiedAt { get; private set; }

    private AggregateModifiedEvent() : base() { }

    /// <summary>
    /// Initializes a new instance of the <see cref="AggregateModifiedEvent"/> audit record.
    /// </summary>
    /// <param name="aggregateType">The class type classification name of the target aggregate root.</param>
    /// <param name="aggregateId">The string representation of the target aggregate identity key.</param>
    /// <param name="modifierId">The identity descriptor of the executing actor.</param>
    /// <param name="tenantId">The multi-tenant logical isolation tracking token, if applicable.</param>
    /// <param name="modifiedAt">The localized timestamp capturing the mutation mark.</param>
    public AggregateModifiedEvent(
        string aggregateType,
        string aggregateId,
        string modifierId,
        string? tenantId,
        DateTimeOffset modifiedAt)
        : base(aggregateType, aggregateId)
    {
        ModifierId = string.IsNullOrWhiteSpace(modifierId) ? throw new ArgumentException("Modifier identity mapping cannot be blank.", nameof(modifierId)) : modifierId;
        TenantId = tenantId;
        ModifiedAt = modifiedAt;
    }
}

/// <summary>
/// A cross-cutting infrastructure audit event raised when an Aggregate Root transitions into a soft-deleted logical state.
/// </summary>
public sealed class AggregateSoftDeletedEvent : DomainEventBase
{
    /// <summary>
    /// Gets the unique identifier of the user or system principal who logically flagged the destruction of this record.
    /// </summary>
    public string DeleterId { get; private set; } = null!;

    /// <summary>
    /// Gets the tenant context identifier partition containing this record.
    /// </summary>
    public string? TenantId { get; private set; }

    /// <summary>
    /// Gets the exact timezone-aware point in time when the soft-deletion process was executed.
    /// </summary>
    public DateTimeOffset DeletedAt { get; private set; }

    private AggregateSoftDeletedEvent() : base() { }

    /// <summary>
    /// Initializes a new instance of the <see cref="AggregateSoftDeletedEvent"/> audit record.
    /// </summary>
    /// <param name="aggregateType">The class type classification name of the target aggregate root.</param>
    /// <param name="aggregateId">The string representation of the target aggregate identity key.</param>
    /// <param name="deleterId">The identity descriptor of the destroying actor.</param>
    /// <param name="tenantId">The multi-tenant logical isolation tracking token, if applicable.</param>
    /// <param name="deletedAt">The localized timestamp completing the soft-deletion marker.</param>
    public AggregateSoftDeletedEvent(
        string aggregateType,
        string aggregateId,
        string deleterId,
        string? tenantId,
        DateTimeOffset deletedAt)
        : base(aggregateType, aggregateId)
    {
        DeleterId = string.IsNullOrWhiteSpace(deleterId) ? throw new ArgumentException("Deleter identity mapping cannot be blank.", nameof(deleterId)) : deleterId;
        TenantId = tenantId;
        DeletedAt = deletedAt;
    }
}

/// <summary>
/// A cross-cutting infrastructure audit event raised when a previously soft-deleted Aggregate Root is successfully resurrected back into active operations.
/// </summary>
public sealed class AggregateRestoredEvent : DomainEventBase
{
    /// <summary>
    /// Gets the unique identifier of the user or actor who reversed the soft-deletion state.
    /// </summary>
    public string RestorerId { get; private set; } = null!;

    /// <summary>
    /// Gets the tenant context identifier partition containing this record.
    /// </summary>
    public string? TenantId { get; private set; }

    /// <summary>
    /// Gets the exact timezone-aware point in time when the restoration process was finalized.
    /// </summary>
    public DateTimeOffset RestoredAt { get; private set; }

    private AggregateRestoredEvent() : base() { }

    /// <summary>
    /// Initializes a new instance of the <see cref="AggregateRestoredEvent"/> audit record.
    /// </summary>
    /// <param name="aggregateType">The class type classification name of the target aggregate root.</param>
    /// <param name="aggregateId">The string representation of the target aggregate identity key.</param>
    /// <param name="restorerId">The identity descriptor of the restoring actor.</param>
    /// <param name="tenantId">The multi-tenant logical isolation tracking token, if applicable.</param>
    /// <param name="restoredAt">The localized timestamp completing the restoration marker.</param>
    public AggregateRestoredEvent(
        string aggregateType,
        string aggregateId,
        string restorerId,
        string? tenantId,
        DateTimeOffset restoredAt)
        : base(aggregateType, aggregateId)
    {
        RestorerId = string.IsNullOrWhiteSpace(restorerId) ? throw new ArgumentException("Restorer identity mapping cannot be blank.", nameof(restorerId)) : restorerId;
        TenantId = tenantId;
        RestoredAt = restoredAt;
    }
}
